// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {airDrop} from "../src/airDrop.sol";

contract InvMutTest is Test {
    airDrop c;
    function setUp() public { c = new airDrop(); }
    function testRegression_property() public {
        address dummyToken = address(new DummyToken());
        address[] memory recipients = new address[](1);
        recipients[0] = address(0x123);
        c.transfer(address(this), dummyToken, recipients, 1, 0);
        assertEq(DummyToken(dummyToken).lastRecipient(), address(0x123));
    }
}

contract DummyToken {
    address public lastRecipient;
    function transferFrom(address, address to, uint256) external returns (bool) {
        lastRecipient = to;
        return true;
    }
}
